/*!50003 CREATE*/ /*!50017 DEFINER=`Diego.Garrido`@`%`*/ /*!50003 TRIGGER `trg_tbc_categories_after_insert` AFTER INSERT ON `tb_categories` FOR EACH ROW BEGIN
    INSERT INTO tb_logs
    (
        table_name,
        record_id,
        table_operation,
        db_user,
        table_description
    )
    VALUES
    (
        'tb_categories',
        NEW.ID,
        'Create',
        USER(),
        CONCAT(
            'Categoria creada: "',
            NEW.name,
            '". Descripcion: ',
            COALESCE(NEW.description, 'NULL'),
            ', Categoria superior: ',
            COALESCE(CAST(NEW.sup_id_category AS CHAR), 'NULL'),
            ', Status: ',
            CAST(NEW.status AS UNSIGNED)
        )
    );
END */;;
